#!/usr/bin/env python3
"""Auditable IPv6 lookup pipeline: compile + lookup (SCAMP-Trie-like codec)."""
import sys
import json
import math

FULL = (1 << 128) - 1
HEXCHARS = set('0123456789abcdefABCDEF')
ADDRCHARS = HEXCHARS | {':'}


class Invalid(Exception):
    pass


# ---------------- strict JSON parsing ----------------

def _const(x):
    raise Invalid()

def _float(x):
    raise Invalid()

def _hook(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Invalid()
        d[k] = v
    return d

def loads_strict(s):
    return json.loads(s, object_pairs_hook=_hook,
                      parse_constant=_const, parse_float=_float)


def check_depth(bs):
    depth = 0
    i = 0
    n = len(bs)
    instr = False
    while i < n:
        c = bs[i]
        if instr:
            if c == 0x5c:  # backslash
                i += 2
                continue
            if c == 0x22:
                instr = False
            i += 1
            continue
        if c == 0x22:
            instr = True
            i += 1
            continue
        if c == 0x7b or c == 0x5b:  # { [
            depth += 1
            if depth > 200:
                raise Invalid()
        elif c == 0x7d or c == 0x5d:  # } ]
            depth -= 1
            if depth < 0:
                raise Invalid()
        i += 1
    if instr:
        raise Invalid()


def first_nonws(bs):
    ws = (0x20, 0x09, 0x0a, 0x0d)
    for b in bs:
        if b not in ws:
            return b
    return None


# ---------------- IPv6 parsing / formatting ----------------

def parse_ipv6(s):
    if not isinstance(s, str) or s == '':
        raise Invalid()
    for ch in s:
        if ch not in ADDRCHARS:
            raise Invalid()
    if s.count('::') > 1:
        raise Invalid()
    if '::' in s:
        left, right = s.split('::')
        lg = left.split(':') if left != '' else []
        rg = right.split(':') if right != '' else []
        groups = lg + rg
        if len(groups) >= 8:
            raise Invalid()
        vals = []
        for g in groups:
            if g == '' or len(g) > 4:
                raise Invalid()
            for ch in g:
                if ch not in HEXCHARS:
                    raise Invalid()
            vals.append(int(g, 16))
        zeros = 8 - len(vals)
        allvals = vals[:len(lg)] + [0] * zeros + vals[len(lg):]
        if len(allvals) != 8:
            raise Invalid()
    else:
        parts = s.split(':')
        if len(parts) != 8:
            raise Invalid()
        allvals = []
        for g in parts:
            if g == '' or len(g) > 4:
                raise Invalid()
            for ch in g:
                if ch not in HEXCHARS:
                    raise Invalid()
            allvals.append(int(g, 16))
    val = 0
    for g in allvals:
        val = (val << 16) | g
    return val


_LEN_OK = set('0123456789')

def parse_prefix(s):
    if not isinstance(s, str):
        raise Invalid()
    if s.count('/') != 1:
        raise Invalid()
    addr, ln = s.split('/')
    val = parse_ipv6(addr)
    if ln == '' or any(ch not in _LEN_OK for ch in ln):
        raise Invalid()
    if len(ln) > 1 and ln[0] == '0':
        raise Invalid()
    length = int(ln)
    if length < 0 or length > 128:
        raise Invalid()
    if length < 128:
        mask = (1 << (128 - length)) - 1
        if val & mask != 0:
            raise Invalid()
    return val, length


def fmt(addr, length=None):
    groups = [(addr >> (112 - 16 * i)) & 0xFFFF for i in range(8)]
    best_start = -1
    best_len = 0
    i = 0
    while i < 8:
        if groups[i] == 0:
            j = i
            while j < 8 and groups[j] == 0:
                j += 1
            run = j - i
            if run >= 2 and run > best_len:
                best_len = run
                best_start = i
            i = j
        else:
            i += 1
    if best_start >= 0:
        left = ':'.join('%x' % g for g in groups[:best_start])
        right = ':'.join('%x' % g for g in groups[best_start + best_len:])
        s = left + '::' + right
    else:
        s = ':'.join('%x' % g for g in groups)
    if length is not None:
        s += '/%d' % length
    return s


def trunc(val, b):
    if b <= 0:
        return 0
    if b >= 128:
        return val
    return val & (FULL ^ ((1 << (128 - b)) - 1))


def alignk(x, k):
    return k * ((x + k - 1) // k)


# ---------------- compile validation ----------------

def validate_compile(req):
    if not isinstance(req, dict):
        raise Invalid()
    if set(req.keys()) != {'op', 'fib', 'capacities', 'max_stride'}:
        raise Invalid()
    if req['op'] != 'compile':
        raise Invalid()
    fib = req['fib']
    caps = req['capacities']
    ms = req['max_stride']
    if type(ms) is not int or not (1 <= ms <= 32):
        raise Invalid()
    if not isinstance(caps, list):
        raise Invalid()
    S = len(caps)
    if not (4 <= S <= 16):
        raise Invalid()
    for x in caps:
        if type(x) is not int or x <= 0 or x > 10 ** 9:
            raise Invalid()
    if not isinstance(fib, list):
        raise Invalid()
    if len(fib) > 2048:
        raise Invalid()
    parsed = []
    seen = set()
    for rec in fib:
        if not isinstance(rec, dict):
            raise Invalid()
        if set(rec.keys()) != {'prefix', 'hop'}:
            raise Invalid()
        p = rec['prefix']
        h = rec['hop']
        if not isinstance(p, str):
            raise Invalid()
        val, length = parse_prefix(p)
        if type(h) is not int or h < 0 or h > 65535:
            raise Invalid()
        key = (val, length)
        if key in seen:
            raise Invalid()
        seen.add(key)
        parsed.append((val, length, h))
    return parsed, caps, ms, S


# ---------------- cost map + DP ----------------

def build_costmap(parsed, max_stride):
    cost = {}
    for b in range(0, 128):
        if b == 0:
            groups = {0: parsed}
        else:
            groups = {}
            for t in parsed:
                val, length, hop = t
                if length > b:
                    k = trunc(val, b)
                    g = groups.get(k)
                    if g is None:
                        groups[k] = [t]
                    else:
                        g.append(t)
        if b != 0 and not groups:
            for e in range(b + 1, min(b + max_stride, 128) + 1):
                cost[(b, e)] = 0
            continue
        for e in range(b + 1, min(b + max_stride, 128) + 1):
            span = e - b
            eb = 32 + alignk(span, 8)
            total = 0
            for k, plist in groups.items():
                rs = 0
                eset = None
                for (val, length, hop) in plist:
                    if length <= e:
                        rs += 32 + alignk(length - b, 8)
                    else:
                        if eset is None:
                            eset = set()
                        eset.add(trunc(val, e))
                ne = 0 if eset is None else len(eset)
                total += alignk(128 + rs + ne * eb, 64)
            cost[(b, e)] = total
    return cost


def frac_lt(a, b):
    return a[0] * b[1] < b[0] * a[1]


def solve_cuts(costmap, caps, max_stride, S):
    best = [dict() for _ in range(S + 1)]
    pred = [dict() for _ in range(S + 1)]
    best[0][0] = (0, 1)
    for i in range(S):
        cap = caps[i]
        bi = best[i]
        bn = best[i + 1]
        pn = pred[i + 1]
        for d, fr in bi.items():
            emax = d + max_stride
            if emax > 128:
                emax = 128
            base_cost = None
            for e in range(d + 1, emax + 1):
                cost = costmap[(d, e)]
                cf = (cost, cap)
                cand = cf if frac_lt(fr, cf) else fr
                cur = bn.get(e)
                if cur is None or frac_lt(cand, cur):
                    bn[e] = cand
                    pn[e] = d
    if 128 not in best[S]:
        return None
    cuts = [0] * (S + 1)
    cuts[S] = 128
    d = 128
    for i in range(S, 0, -1):
        d = pred[i][d]
        cuts[i - 1] = d
    return cuts, best[S][128]


# ---------------- image building ----------------

def build_stages(parsed, cuts, max_stride):
    S = len(cuts) - 1
    stage_keys = []
    stage_groups = []
    for i in range(S):
        b = cuts[i]
        if b == 0:
            groups = {0: parsed}
        else:
            groups = {}
            for t in parsed:
                val, length, hop = t
                if length > b:
                    k = trunc(val, b)
                    g = groups.get(k)
                    if g is None:
                        groups[k] = [t]
                    else:
                        g.append(t)
        keys = sorted(groups.keys())
        stage_keys.append(keys)
        stage_groups.append(groups)

    stages = []
    used = []
    for i in range(S):
        b = cuts[i]
        e = cuts[i + 1]
        span = e - b
        eb = 32 + alignk(span, 8)
        groups = stage_groups[i]
        keys = stage_keys[i]
        if i + 1 < S:
            next_pos = {k: idx for idx, k in enumerate(stage_keys[i + 1])}
        else:
            next_pos = None
        nodes = []
        totalcost = 0
        for k in keys:
            plist = groups[k]
            rules = []
            rs = 0
            edges_map = {}
            for (val, length, hop) in plist:
                if length <= e:
                    rules.append((length, val, hop))
                    rs += 32 + alignk(length - b, 8)
                else:
                    edges_map[trunc(val, e)] = True
            rules.sort(key=lambda r: (r[0], r[1]))
            node_rules = [{"prefix": fmt(r[1], r[0]), "hop": r[2]} for r in rules]
            node_edges = []
            if e < 128 and edges_map:
                for ek in sorted(edges_map.keys()):
                    node_edges.append({"prefix": fmt(ek, e), "child": next_pos[ek]})
            ne = len(node_edges)
            cost = alignk(128 + rs + ne * eb, 64)
            totalcost += cost
            nodes.append({"prefix": fmt(k, b), "rules": node_rules, "edges": node_edges})
        used.append(totalcost)
        stages.append({"nodes": nodes})
    return stages, used


def reduce_frac(n, d):
    if n == 0:
        return (0, 1)
    g = math.gcd(n, d)
    return (n // g, d // g)


def max_ratio(used, caps):
    bn = 0
    bd = 1
    for u, c in zip(used, caps):
        if u * bd > bn * c:
            bn = u
            bd = c
    return reduce_frac(bn, bd)


# ---------------- handlers ----------------

def handle_compile(req):
    parsed, caps, ms, S = validate_compile(req)
    costmap = build_costmap(parsed, ms)
    res = solve_cuts(costmap, caps, ms, S)
    if res is None:
        return {"status": "infeasible"}
    cuts, _ = res
    stages, used = build_stages(parsed, cuts, ms)
    num, den = max_ratio(used, caps)
    return {
        "status": "ok",
        "capacities": caps,
        "max_stride": ms,
        "cuts": cuts,
        "stages": stages,
        "used_bits": used,
        "peak": {"num": num, "den": den},
    }


def validate_lookup_image(image):
    if not isinstance(image, dict):
        raise Invalid()
    if set(image.keys()) != {'status', 'capacities', 'max_stride', 'cuts',
                              'stages', 'used_bits', 'peak'}:
        raise Invalid()
    if image['status'] != 'ok':
        raise Invalid()
    caps = image['capacities']
    ms = image['max_stride']
    cuts = image['cuts']
    stages = image['stages']
    used = image['used_bits']
    peak = image['peak']

    if not isinstance(caps, list):
        raise Invalid()
    S = len(caps)
    if not (4 <= S <= 16):
        raise Invalid()
    for x in caps:
        if type(x) is not int or x <= 0 or x > 10 ** 9:
            raise Invalid()
    if type(ms) is not int or not (1 <= ms <= 32):
        raise Invalid()

    if not isinstance(cuts, list) or len(cuts) != S + 1:
        raise Invalid()
    for c in cuts:
        if type(c) is not int or c < 0 or c > 128:
            raise Invalid()
    if cuts[0] != 0 or cuts[S] != 128:
        raise Invalid()
    for i in range(S):
        if cuts[i + 1] <= cuts[i] or cuts[i + 1] - cuts[i] > ms:
            raise Invalid()

    if not isinstance(stages, list) or len(stages) != S:
        raise Invalid()
    fib = []
    seen = set()
    for si in range(S):
        st = stages[si]
        if not isinstance(st, dict) or set(st.keys()) != {'nodes'}:
            raise Invalid()
        nodes = st['nodes']
        if not isinstance(nodes, list):
            raise Invalid()
        b = cuts[si]
        e = cuts[si + 1]
        for nd in nodes:
            if not isinstance(nd, dict) or set(nd.keys()) != {'prefix', 'rules', 'edges'}:
                raise Invalid()
            pv, pl = parse_prefix(nd['prefix'])
            if pl != b or fmt(pv, pl) != nd['prefix']:
                raise Invalid()
            rules = nd['rules']
            edges = nd['edges']
            if not isinstance(rules, list) or not isinstance(edges, list):
                raise Invalid()
            for r in rules:
                if not isinstance(r, dict) or set(r.keys()) != {'prefix', 'hop'}:
                    raise Invalid()
                rv, rl = parse_prefix(r['prefix'])
                if fmt(rv, rl) != r['prefix']:
                    raise Invalid()
                h = r['hop']
                if type(h) is not int or h < 0 or h > 65535:
                    raise Invalid()
                key = (rv, rl)
                if key in seen:
                    raise Invalid()
                seen.add(key)
                fib.append((rv, rl, h))
            for ed in edges:
                if not isinstance(ed, dict) or set(ed.keys()) != {'prefix', 'child'}:
                    raise Invalid()
                ev, el = parse_prefix(ed['prefix'])
                if el != e or fmt(ev, el) != ed['prefix']:
                    raise Invalid()
                ch = ed['child']
                if type(ch) is not int or ch < 0:
                    raise Invalid()

    if len(fib) > 2048:
        raise Invalid()
    if not isinstance(used, list) or len(used) != S:
        raise Invalid()
    for u in used:
        if type(u) is not int or u < 0:
            raise Invalid()
    if not isinstance(peak, dict) or set(peak.keys()) != {'num', 'den'}:
        raise Invalid()
    pn = peak['num']
    pd = peak['den']
    if type(pn) is not int or type(pd) is not int:
        raise Invalid()
    if pd <= 0 or pn < 0:
        raise Invalid()
    if math.gcd(pn, pd) != 1:
        raise Invalid()

    exp_stages, exp_used = build_stages(fib, cuts, ms)
    if exp_stages != stages:
        raise Invalid()
    if exp_used != used:
        raise Invalid()
    for u, c in zip(exp_used, caps):
        if u > c:
            raise Invalid()
    ep = max_ratio(exp_used, caps)
    if (ep[0], ep[1]) != (pn, pd):
        raise Invalid()
    return fib, cuts, caps, S, ms


def match(addr, val, length):
    if length == 0:
        return True
    sh = 128 - length
    return (addr >> sh) == (val >> sh)


def handle_lookup(req):
    if set(req.keys()) != {'op', 'image', 'addresses'}:
        raise Invalid()
    if req['op'] != 'lookup':
        raise Invalid()
    image = req['image']
    addresses = req['addresses']
    fib, cuts, caps, S, ms = validate_lookup_image(image)
    if not isinstance(addresses, list):
        raise Invalid()
    if len(addresses) > 20000:
        raise Invalid()
    parsed_addrs = []
    for a in addresses:
        if not isinstance(a, str):
            raise Invalid()
        # address must not contain slash
        if '/' in a:
            raise Invalid()
        parsed_addrs.append(parse_ipv6(a))

    # compile traversal structure
    stages = image['stages']
    comp = []
    for si in range(S):
        nodes = []
        for nd in stages[si]['nodes']:
            rules = []
            for r in nd['rules']:
                rv, rl = parse_prefix(r['prefix'])
                rules.append((rv, rl, r['hop']))
            edges = []
            for ed in nd['edges']:
                ev, el = parse_prefix(ed['prefix'])
                edges.append((ev, el, ed['child']))
            nodes.append((rules, edges))
        comp.append(nodes)

    answers = []
    for addr in parsed_addrs:
        best_hop = None
        best_len = -1
        idx = 0
        for i in range(S):
            rules, edges = comp[i][idx]
            for (rv, rl, hop) in rules:
                if rl > best_len and match(addr, rv, rl):
                    best_len = rl
                    best_hop = hop
            if i + 1 < S:
                child = None
                for (ev, el, ch) in edges:
                    if match(addr, ev, el):
                        child = ch
                        break
                if child is None:
                    break
                idx = child
        if best_hop is None:
            answers.append({"hop": None, "prefix_length": None})
        else:
            answers.append({"hop": best_hop, "prefix_length": best_len})
    return {"status": "ok", "answers": answers}


def process_line(bs):
    if len(bs) == 0:
        raise Invalid()
    fb = first_nonws(bs)
    if fb is None or fb != 0x7b:
        raise Invalid()
    check_depth(bs)
    s = bs.decode('utf-8')
    obj = loads_strict(s)
    if not isinstance(obj, dict):
        raise Invalid()
    op = obj.get('op')
    if op == 'compile':
        return handle_compile(obj)
    elif op == 'lookup':
        return handle_lookup(obj)
    else:
        raise Invalid()


def main():
    out = sys.stdout
    for line in sys.stdin.buffer:
        if line.endswith(b'\n'):
            line = line[:-1]
        try:
            resp = process_line(line)
        except Invalid:
            resp = {"status": "invalid"}
        except (ValueError, KeyError, TypeError, IndexError,
                RecursionError, MemoryError, UnicodeError, OverflowError):
            resp = {"status": "invalid"}
        out.write(json.dumps(resp, separators=(',', ':')))
        out.write('\n')
        out.flush()


if __name__ == '__main__':
    main()
